-- Course: Signals, DSP and Estimation

from scipy.signal import firwin, freqz, lfilter

fs, f_pass, f_stop = 10_000.0, 2_000.0, 2_500.0           # Hz
N = int(np.ceil(3.3 * fs / (f_stop - f_pass))) | 1          # odd, about 3.3 fs/df taps
h = firwin(N, (f_pass + f_stop) / 2, window="hamming", fs=fs)
w, H = freqz(h, worN=4096, fs=fs)
print(f"{N} taps, delay {(N-1)/2/fs*1e3:.2f} ms")
print(f"gain at {f_stop:.0f} Hz: {20*np.log10(abs(H[np.argmin(abs(w-f_stop))])):.1f} dB")

x = np.random.default_rng(0).standard_normal(20_000)
y = lfilter(h, 1.0, x)                                      # causal output, delayed by (N-1)/2 samples', 'Check the delay and the stopband before using a filter in an event detector', 0);
from scipy.signal import welch, spectrogram

fs = 5_000
x = np.random.default_rng(1).standard_normal(60_000) * 10.0     # 12 s, about 10 g rms, white
f, pxx = welch(x, fs=fs, window="hann", nperseg=2048, noverlap=1024)
band = (f >= 20) & (f <= 2000)
grms = np.sqrt(np.trapezoid(pxx[band], f[band]))
print(f"df = {f[1]:.2f} Hz, Grms (20 to 2000 Hz) = {grms:.1f} g")

# Spectrogram: 100 ms window gives 10 Hz resolution
fx, tx, S = spectrogram(x, fs=fs, nperseg=int(0.1 * fs), noverlap=int(0.05 * fs))
print("spectrogram bins:", S.shape)', 'Report the resolution, window and number of averages with every PSD', 1);

dt, sa, sh = 0.1, 0.5, 2.0
F = np.array([[1, dt], [0, 1]]); B = np.array([[0.5 * dt**2], [dt]]); H = np.array([[1.0, 0.0]])
Q = sa**2 * np.array([[dt**4 / 4, dt**3 / 2], [dt**3 / 2, dt**2]]); R = np.array([[sh**2]])

x = np.zeros((2, 1)); P = np.diag([100.0, 25.0])
def step(x, P, a, z):
    x = F @ x + B * a                      # predict with accelerometer input
    P = F @ P @ F.T + Q
    S = H @ P @ H.T + R                    # innovation variance
    nu = z - H @ x
    if (nu**2 / S).item() > 9.0:             # 3-sigma gate: ignore a wild barometer reading
        return x, P, (nu**2 / S).item()
    K = P @ H.T @ np.linalg.inv(S)
    x = x + K * nu
    P = (np.eye(2) - K @ H) @ P @ (np.eye(2) - K @ H).T + K @ R @ K.T   # Joseph form
    return x, P, (nu**2 / S).item()

x, P, nis = step(x, P, a=0.0, z=np.array([[3.0]]))
print("altitude, velocity:", x.ravel(), " NIS:", round(nis, 2))', 'NIS should stay below 3.84 about 95 percent of the time', 2);
