INSERT INTO courses (slug, title, subtitle, description, discipline_id, level, instructor_name, instructor_role, updated, hue, position) VALUES ('signals-dsp-estimation', 'Signals, DSP and Estimation', 'Sampling, filters, the FFT and Kalman filters, from first principles to a flight-data pipeline.', 'Learn the signal-processing and estimation tools behind every instrument on a test stand or a rocket: how signals are sampled and quantized, how digital filters are designed and what they cost in delay, how the FFT and Welch''s method turn a log into a spectrum, and how least squares and Kalman filters combine noisy sensors into one estimate. Every worked number is computed, and the course ends by specifying a complete processing pipeline for a vibration channel and a barometer-plus-accelerometer altitude filter.', 'signals-dsp', 'Foundation', 'DUT Space Science Centre', 'Launch and instrumentation team', '2026-11', 150, 3);
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'outcome', 0, 'Describe a signal by its amplitude, rms, spectrum and noise, and work in decibels');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'outcome', 1, 'Predict the effect of sampling and quantization: the alias frequency, the noise floor and the effective number of bits');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'outcome', 2, 'Design and compare FIR and IIR filters, and say what each costs in delay and computation');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'outcome', 3, 'Compute a spectrum with the FFT, choose a window, and estimate a PSD, Grms and a frequency response with a stated error');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'outcome', 4, 'Combine noisy measurements by weighted least squares and a recursive filter');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'outcome', 5, 'Build and tune a Kalman filter, check it with its innovations, and say when it will fail');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'prerequisite', 0, 'Calculus and basic trigonometry, including complex numbers');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'prerequisite', 1, 'Comfort reading short Python or C code');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'prerequisite', 2, 'No prior signal-processing course is needed');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'audience', 0, 'Engineers building or reviewing measurement and logging systems');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'audience', 1, 'Students preparing for the IMU and vibration work with ASRI');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('signals-dsp-estimation', 'audience', 2, 'Anyone who has to trust a spectrum, a filter output or a fused estimate');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('signals-dsp-estimation', 'm1', 'Signals, systems and sampling', 'Describing a signal, what a linear system does to it, and what sampling and quantization cost.', 0);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'signals-basics', 'm1', 'Signals, amplitude and decibels', 30, 'Sinusoids, rms, spectra, noise and the decibel, with the numbers you will meet on a test stand.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 0, 'h', '{"text":"What a signal is"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 1, 'p', '{"text":"A signal is a quantity that varies with time: an accelerometer voltage, a chamber pressure, a gyro rate. Almost every useful signal can be built from sinusoids, and that is why frequency is the central idea of signal processing."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 2, 'eq', '{"text":"x(t) = A\\sin(2\\pi f t + \\varphi)","name":"Sinusoid","caption":"Amplitude A, frequency f in hertz, phase φ"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 3, 'ul', '{"items":["The **peak** is $A$. The **rms** is $A/\\sqrt2$, so a 10 g peak sine has an rms of 7.07 g.","The **period** is $T = 1/f$ and the angular frequency is $\\omega = 2\\pi f$.","A real signal such as vibration is a sum of many sinusoids. Its **spectrum** shows how much amplitude or power sits at each frequency."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 4, 'h', '{"text":"Decibels"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 5, 'p', '{"text":"Ratios of amplitude or power span huge ranges, so engineers use decibels, which turn multiplication into addition."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 6, 'eq', '{"text":"\\mathrm{dB} = 20\\log_{10}\\frac{A_1}{A_2} = 10\\log_{10}\\frac{P_1}{P_2}","name":"Decibel"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 7, 'table', '{"head":["Ratio of amplitudes","Decibels"],"rows":[["2","+6.02 dB"],["10","+20 dB"],["1 000","+60 dB"],["0.707","−3 dB (half power)"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 8, 'h', '{"text":"Signal and noise"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 9, 'p', '{"text":"Every measurement is signal plus noise. The signal-to-noise ratio compares their rms values."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 10, 'eq', '{"text":"\\mathrm{SNR} = 20\\log_{10}\\frac{x_{rms,signal}}{x_{rms,noise}}","name":"Signal-to-noise ratio"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 11, 'eq', '{"text":"\\frac{1}{T}\\int |x(t)|^2\\,dt = \\sum_k |c_k|^2","name":"Parseval''s theorem","caption":"The power in time equals the power in the spectrum"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'signals-basics', 12, 'callout', '{"kind":"key","title":"Power is conserved between domains","text":"Parseval means you can compute the rms of a record either from its samples or by adding up its spectrum. This is how a PSD becomes a Grms later in the course."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'signals-basics', 0, 'A sinusoid has rms $A/\sqrt2$; the spectrum shows how power is spread over frequency.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'signals-basics', 1, 'Decibels turn ratios into sums: 6 dB is a factor of 2 in amplitude and 60 dB a factor of 1 000.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'signals-basics', 2, 'Power is the same whether you sum samples or sum the spectrum (Parseval).');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'signals-basics', 0, 'The Scientist and Engineer''s Guide to Digital Signal Processing, ch. 2 and 5', 'Smith', 'https://www.dspguide.com/', 'Statistics, probability and noise; linear systems. Local copy: study library');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'lti-convolution', 'm1', 'Linear systems and convolution', 35, 'The impulse response, convolution, frequency response, and the first-order low-pass as a worked example.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 0, 'h', '{"text":"The systems you will meet are linear and time-invariant"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 1, 'p', '{"text":"A sensor, an amplifier, a filter and a structure all behave, to a good approximation, as **linear time-invariant (LTI)** systems: doubling the input doubles the output, and delaying the input delays the output by the same amount."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 2, 'p', '{"text":"An LTI system is completely described by its **impulse response** $h$, the output for a single sharp input. The output for any input is the **convolution** of the input with $h$."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 3, 'eq', '{"text":"y[n] = \\sum_{k} h[k]\\,x[n-k] = (h * x)[n]","name":"Convolution"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 4, 'ul', '{"items":["A **moving average** of N samples is a convolution with N equal values of 1/N.","A **cascade** of systems convolves their impulse responses, and in the frequency domain simply multiplies the responses.","Convolution in time is multiplication in frequency, which is why filters are designed in the frequency domain."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 5, 'h', '{"text":"Frequency response"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 6, 'p', '{"text":"Feed a sinusoid of frequency $f$ into an LTI system and the output is a sinusoid at the same frequency, with a different amplitude and phase. The **frequency response** $H(f)$ records that gain and phase at each frequency."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 7, 'h', '{"text":"A worked example: the RC low-pass"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 8, 'eq', '{"text":"H(f) = \\frac{1}{1 + j f/f_c}, \\qquad f_c = \\frac{1}{2\\pi RC}","name":"First-order low-pass"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 9, 'p', '{"text":"A 10 kΩ resistor and a 16 nF capacitor give $f_c = 1/(2\\pi \\times 10^4 \\times 16\\times10^{-9}) = 995$ Hz. At $f_c$ the gain is 0.707 (−3 dB) and the phase lag is 45°. Above $f_c$ the gain falls at 20 dB per decade, which is far too slow to be an anti-alias filter by itself."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'lti-convolution', 10, 'callout', '{"kind":"key","title":"A filter changes time as well as amplitude","text":"Every filter that changes the frequency content also delays the signal. The delay is part of the filter, not an error, and you must account for it when you detect events or align records."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'lti-convolution', 0, 'An LTI system is fully described by its impulse response; the output is the input convolved with it.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'lti-convolution', 1, 'Convolution in time is multiplication in frequency, so a cascade multiplies the responses.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'lti-convolution', 2, 'An RC low-pass has $f_c = 1/(2\pi RC)$; a 10 kΩ and 16 nF pair gives 995 Hz.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'lti-convolution', 0, 'The Scientist and Engineer''s Guide to Digital Signal Processing, ch. 5 to 7', 'Smith', 'https://www.dspguide.com/', 'Linear systems, convolution and its properties');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'sampling-quantization', 'm1', 'Sampling and quantization', 35, 'The alias frequency, the quantization noise floor, the effective number of bits and what oversampling buys.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 0, 'h', '{"text":"Sampling folds frequencies"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 1, 'p', '{"text":"Sampling at $f_s$ measures a signal at instants $1/f_s$ apart. A frequency $f$ above half the sample rate is indistinguishable from a lower one, its **alias**."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 2, 'eq', '{"text":"f_{alias} = \\left| f - k\\,f_s \\right|, \\quad k = \\text{nearest integer to } f/f_s","name":"Alias frequency"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 3, 'p', '{"text":"A 7 kHz tone sampled at 10 kS/s appears at |7 000 − 10 000| = 3 kHz. A 12 kHz tone appears at 2 kHz. Once sampled, no processing can tell them from genuine low-frequency content, so the anti-alias filter must come before the converter."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 4, 'h', '{"text":"Quantization turns a smooth value into a step"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 5, 'p', '{"text":"An N-bit converter divides its full-scale range into $2^N$ steps of size $\\Delta$, the least significant bit (LSB). The rounding error is roughly uniform, with an rms of $\\Delta/\\sqrt{12}$."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 6, 'eq', '{"text":"\\Delta = \\frac{FS}{2^N}, \\qquad q_{rms} = \\frac{\\Delta}{\\sqrt{12}}, \\qquad \\mathrm{SNR} \\approx 6.02\\,N + 1.76\\ \\mathrm{dB}","name":"Quantization noise"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 7, 'table', '{"head":["Resolution","Ideal SNR (full-scale sine)"],"rows":[["12 bits","74 dB"],["16 bits","98 dB"],["24 bits","146 dB (limited by analog noise in practice)"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 8, 'p', '{"text":"A ±16 g accelerometer read by a 16-bit converter has an LSB of $32/65\\,536 = 0.488$ mg and a quantization noise of 0.141 mg rms."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 9, 'h', '{"text":"Effective bits and oversampling"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 10, 'ul', '{"items":["Real converters have analog noise and distortion on top of quantization. The **effective number of bits** is $\\mathrm{ENOB} = (\\mathrm{SINAD} - 1.76)/6.02$, so an 80 dB converter has 13 bits.","**Oversampling** by a factor $M$ spreads the quantization noise over a wider band; filtering to the band of interest removes the rest and improves the SNR by $10\\log_{10}M$. Each factor of 4 buys one bit.","Sigma-delta converters push this much further by shaping the noise out of the band."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'sampling-quantization', 11, 'callout', '{"kind":"warn","title":"Resolution is not accuracy","text":"A 24-bit converter does not give a 24-bit measurement. Its accuracy is limited by the reference, the analog front end and the sensor. Choose bits from the noise floor you can actually reach."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'sampling-quantization', 0, 'A tone at $f$ aliases to $|f - kf_s|$; 7 kHz at 10 kS/s appears at 3 kHz.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'sampling-quantization', 1, 'Quantization SNR is about $6.02N + 1.76$ dB; the noise is $\Delta/\sqrt{12}$ rms.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'sampling-quantization', 2, 'Oversampling by 4 buys one bit; real converters are limited by analog noise, so quote ENOB.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'sampling-quantization', 0, 'The Scientist and Engineer''s Guide to Digital Signal Processing, ch. 3', 'Smith', 'https://www.dspguide.com/', 'ADC and DAC: sampling, quantization, dither');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'sampling-quantization', 1, 'Antialiasing filter circuit design for single-ended ADC input (SBAA282)', 'Texas Instruments', NULL, 'Study library #19');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm1', 0, 'A 12 kHz tone is sampled at 10 kS/s with no anti-alias filter. It appears at:', '["12 kHz","2 kHz","7 kHz","5 kHz"]', 1, '$|12\,000 - 10\,000| = 2$ kHz.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm1', 1, 'A 16-bit ADC with a ±16 g range has an LSB of about:', '["0.049 mg","0.49 mg","4.9 mg","49 mg"]', 1, '$32 / 65\,536 = 0.488$ mg.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm1', 2, 'A converter measures an SINAD of 80 dB. Its effective number of bits is about:', '["8","10","13","16"]', 2, '$(80 - 1.76)/6.02 = 13.0$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm1', 3, 'Oversampling by a factor of 4 improves the quantization SNR by about:', '["3 dB","6 dB","12 dB","24 dB"]', 1, '$10\log_{10}4 = 6$ dB, which is one bit.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('signals-dsp-estimation', 'm2', 'Digital filters', 'FIR and IIR filters, what each costs, and the practical choices around delay, decimation and noise.', 1);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'fir-filters', 'm2', 'FIR filters', 35, 'Moving averages, windowed-sinc design, linear phase, and how many taps you need.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 0, 'h', '{"text":"A weighted sum of recent samples"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 1, 'p', '{"text":"A **finite impulse response (FIR)** filter outputs a weighted sum of the last N inputs. It has no feedback, so it is always stable, and with symmetric weights it has exactly **linear phase**: every frequency is delayed by the same time."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 2, 'eq', '{"text":"y[n] = \\sum_{k=0}^{N-1} h[k]\\,x[n-k], \\qquad \\text{delay} = \\frac{N-1}{2}\\ \\text{samples}","name":"FIR filter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 3, 'h', '{"text":"The moving average"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 4, 'p', '{"text":"The simplest FIR filter averages N samples. It is excellent at removing random noise (the noise falls by $\\sqrt N$) and poor as a frequency selector: its response has nulls at multiples of $f_s/N$ and a −3 dB point near $0.443 f_s/N$. An 11-sample average at 1 kHz delays the signal by 5 ms."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 5, 'h', '{"text":"Windowed-sinc design"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 6, 'p', '{"text":"An ideal low-pass filter has a sinc-shaped impulse response of infinite length. Truncating it to N points and multiplying by a window gives a practical filter. The window sets the stopband attenuation, and N sets the sharpness."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 7, 'table', '{"head":["Window","Stopband attenuation","Taps for a transition width of Δf"],"rows":[["Rectangular (plain truncation)","about 21 dB","N ≈ 0.9 fs/Δf"],["Hamming","about 53 dB","N ≈ 3.3 fs/Δf"],["Blackman","about 74 dB","N ≈ 5.5 fs/Δf"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 8, 'p', '{"text":"At $f_s = 10$ kHz a Hamming filter with a 500 Hz transition band needs $N = 3.3 \\times 10\\,000 / 500 = 66$ taps. Its delay is 32.5 samples, 3.25 ms."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fir-filters', 9, 'callout', '{"kind":"key","title":"Sharper filters cost delay","text":"Halving the transition width doubles the number of taps and the delay. For event detection and control, choose the widest transition band the application allows."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'fir-filters', 0, 'An FIR filter is always stable, has linear phase if symmetric, and delays by $(N-1)/2$ samples.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'fir-filters', 1, 'A Hamming windowed-sinc filter needs about $N \approx 3.3\,f_s/\Delta f$ taps for about 53 dB.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'fir-filters', 2, 'A moving average removes random noise by $\sqrt N$ but is a poor frequency selector.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'fir-filters', 0, 'The Scientist and Engineer''s Guide to Digital Signal Processing, ch. 14 to 16', 'Smith', 'https://www.dspguide.com/', 'Introduction to digital filters, moving averages and windowed-sinc filters');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'iir-filters', 'm2', 'IIR filters', 35, 'Butterworth designs by the bilinear transform, biquads, stability, phase, and zero-phase filtering offline.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 0, 'h', '{"text":"Feedback buys sharpness"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 1, 'p', '{"text":"An **infinite impulse response (IIR)** filter feeds its own past outputs back in. A handful of coefficients gives the sharp cutoff that an FIR filter needs dozens of taps for. The price is a phase response that is not linear, and stability that must be checked."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 2, 'eq', '{"text":"y[n] = \\sum_{k=0}^{M} b_k\\,x[n-k] - \\sum_{k=1}^{N} a_k\\,y[n-k]","name":"IIR difference equation"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 3, 'h', '{"text":"Designing from an analog prototype"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 4, 'p', '{"text":"The usual route is to start from a good analog filter such as a Butterworth and convert it with the **bilinear transform**, which maps the analog frequency axis onto the digital one with a warping."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 5, 'eq', '{"text":"\\Omega = 2 f_s \\tan\\!\\left(\\frac{\\pi f}{f_s}\\right)","name":"Frequency pre-warping"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 6, 'p', '{"text":"To place a digital cutoff at 2 kHz with $f_s = 10$ kHz, design the analog prototype at $\\Omega_c = 2 \\times 10\\,000\\tan(0.2\\pi) = 14\\,531$ rad/s, not at $2\\pi \\times 2000 = 12\\,566$ rad/s. The attenuation of an order-$n$ Butterworth is the same $10\\log_{10}[1 + (f/f_c)^{2n}]$ as in the analog case, apart from the warping."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 7, 'h', '{"text":"Practical rules"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 8, 'ul', '{"items":["Implement high-order IIR filters as a cascade of second-order sections (**biquads**). A single high-order polynomial loses accuracy in fixed-point and floating-point arithmetic.","Check that every pole lies inside the unit circle; quantizing coefficients can push a pole outside.","The simplest IIR filter is the **exponential average** $y_n = y_{n-1} + \\alpha(x_n - y_{n-1})$. With $\\Delta t = 1$ ms and a 50 ms time constant, $\\alpha = 1 - e^{-\\Delta t/\\tau} = 0.0198$."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 9, 'h', '{"text":"Zero-phase filtering offline"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 10, 'p', '{"text":"A causal filter always delays. After the flight you have the whole record, so you can filter forward and then backward, which cancels the phase and gives zero delay. The magnitude is squared, so a −3 dB point becomes −6 dB at the same frequency, and the effective order doubles."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'iir-filters', 11, 'callout', '{"kind":"warn","title":"Do not use zero-phase filtering for anything that must run in flight","text":"A backward pass needs future samples, so it cannot run in real time. Use it to analyse logs, never inside an event detector."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'iir-filters', 0, 'IIR filters give sharp responses with few coefficients but have nonlinear phase and need a stability check.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'iir-filters', 1, 'Design by the bilinear transform with pre-warping $\Omega = 2f_s\tan(\pi f/f_s)$; implement as biquads.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'iir-filters', 2, 'Forward-backward filtering gives zero phase offline; it is not causal and cannot run in flight.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'iir-filters', 0, 'The Scientist and Engineer''s Guide to Digital Signal Processing, ch. 19 to 21', 'Smith', 'https://www.dspguide.com/', 'Recursive filters, Chebyshev filters and a filter comparison');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'filter-practice', 'm2', 'Choosing and using filters', 30, 'FIR or IIR, decimation, mains notches, delay in event detection and quantization in the filter itself.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 0, 'h', '{"text":"FIR or IIR"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 1, 'table', '{"head":["Need","Choose","Reason"],"rows":[["Linear phase, waveform shape preserved (impulses, shocks)","FIR","No phase distortion"],["Very cheap and sharp, phase not critical","IIR (biquads)","Few operations per sample"],["Real-time event detection","Either, with the shortest delay","Group delay adds to detection time"],["Offline analysis of a log","Zero-phase IIR or FIR","No delay at all"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 2, 'h', '{"text":"Decimation: filter first, then keep every Mth sample"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 3, 'p', '{"text":"Reducing the sample rate without filtering aliases. A vibration channel sampled at 25 kS/s and needed only to 2 kHz can be filtered and reduced to 5 kS/s. Do large ratios in stages: a factor of 25 is a stage of 5 and another of 5, which needs far fewer filter taps than one stage of 25."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 4, 'h', '{"text":"Mains interference"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 5, 'p', '{"text":"South African mains is 50 Hz. Hum shows up at 50 Hz and its harmonics, from cables and power supplies. A narrow **notch filter** removes it, but a notch also rings; fix the grounding and shielding first, and use the notch for what remains."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 6, 'h', '{"text":"Filter delay and event detection"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 7, 'p', '{"text":"A launch detector that waits for 2 g to hold for 100 ms adds to the delay of the filter in front of it. A 5 ms moving-average delay is harmless; a 50 ms delay is not. Add the filter delay and the persistence time when you state when an event was detected."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 8, 'h', '{"text":"The filter itself has finite precision"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 9, 'p', '{"text":"Coefficients and intermediate values are stored with finite bits. In fixed-point, round-off adds noise and can make a high-order direct-form IIR unstable. Use biquad sections and enough bits, or floating point."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'filter-practice', 10, 'callout', '{"kind":"tip","title":"Test the filter with a sine sweep","text":"Feed the implemented filter a sweep from 0 to beyond Nyquist and plot the output amplitude. The measured response should match the design; any aliasing or instability shows up immediately."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'filter-practice', 0, 'Use FIR when waveform shape matters and IIR when you need sharpness cheaply.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'filter-practice', 1, 'Filter before you decimate, and decimate large ratios in stages.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'filter-practice', 2, 'Add the filter''s delay to the detector''s persistence time when you state when an event was detected.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm2', 0, 'A Hamming-window FIR filter needs a 500 Hz transition at 10 kS/s. About how many taps?', '["20","66","200","660"]', 1, '$N \approx 3.3 \times 10\,000/500 = 66$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm2', 1, 'The delay of a symmetric 66-tap FIR filter at 10 kS/s is:', '["0.65 ms","3.25 ms","6.6 ms","66 ms"]', 1, '$(66-1)/2 = 32.5$ samples = 3.25 ms.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm2', 2, 'Why design a digital IIR cutoff with the bilinear pre-warping?', '["To make the filter FIR","The bilinear transform compresses the frequency axis, so the cutoff would land in the wrong place","To remove aliasing","To raise the order"]', 1, 'The mapping $\Omega = 2f_s\tan(\pi f/f_s)$ warps frequency, and the prototype must be designed at the warped value.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm2', 3, 'Why can zero-phase (forward-backward) filtering not run in flight?', '["It needs too much memory only","The backward pass needs future samples","It is unstable","It aliases"]', 1, 'The backward pass runs over the whole record, which is not available in real time.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('signals-dsp-estimation', 'm3', 'The frequency domain', 'The DFT and FFT, windows, spectral estimation, and measuring a frequency response with its coherence.', 2);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'dft-fft', 'm3', 'The DFT, the FFT and windows', 35, 'Bin spacing, leakage, windows, scalloping loss and why the FFT is practical.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 0, 'h', '{"text":"The DFT"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 1, 'p', '{"text":"The **discrete Fourier transform** converts N samples into N frequency bins, each the correlation of the record with a complex sinusoid."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 2, 'eq', '{"text":"X[k] = \\sum_{n=0}^{N-1} x[n]\\,e^{-j2\\pi kn/N}","name":"DFT"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 3, 'eq', '{"text":"\\Delta f = \\frac{f_s}{N} = \\frac{1}{T}","name":"Bin spacing","caption":"T is the record length in seconds"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 4, 'ul', '{"items":["At $f_s = 10$ kHz and $N = 4096$, $\\Delta f = 2.44$ Hz and the record lasts 0.41 s.","Frequency resolution depends only on **record length**. A longer record resolves closer tones; a higher sample rate does not.","The bins above $f_s/2$ mirror those below; only the first $N/2$ are independent for a real signal."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 5, 'h', '{"text":"Leakage and windows"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 6, 'p', '{"text":"The DFT assumes the record repeats forever. A tone that does not fit a whole number of cycles into the record has a jump where the end meets the start, and its energy spreads into neighbouring bins. This is **leakage**. Multiplying the record by a **window** that tapers to zero at the ends reduces it."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 7, 'table', '{"head":["Window","Main-lobe width (bins)","Worst-case amplitude error (scalloping)","Use"],"rows":[["Rectangular","1","3.9 dB","Transients that fit the record, or tones exactly on a bin"],["Hann","1.5","1.4 dB","General spectra and PSD"],["Flat-top","3.8","under 0.01 dB","Measuring the amplitude of a tone"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 8, 'callout', '{"kind":"warn","title":"Zero padding does not add resolution","text":"Padding with zeros interpolates between bins and makes the plot smoother, but it cannot separate two tones closer than 1/T."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 9, 'h', '{"text":"The FFT"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'dft-fft', 10, 'p', '{"text":"Computing the DFT directly takes $N^2$ operations. The **fast Fourier transform** gets the same answer in about $N\\log_2 N$. For $N = 4096$ that is 49 152 operations instead of 16.8 million, a factor of 341. This is what makes spectral analysis on a small microcontroller possible."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'dft-fft', 0, 'Bin spacing is $f_s/N = 1/T$: resolution comes from record length.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'dft-fft', 1, 'A window reduces leakage; Hann for spectra, flat-top for tone amplitude.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'dft-fft', 2, 'The FFT costs $N\log_2 N$, a factor of 341 less than the DFT at $N = 4096$.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'dft-fft', 0, 'The Scientist and Engineer''s Guide to Digital Signal Processing, ch. 8 to 12', 'Smith', 'https://www.dspguide.com/', 'The DFT, its properties and the FFT');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'spectral-estimation', 'm3', 'Spectral estimation: PSD, Welch and the spectrogram', 35, 'Why a single FFT is a noisy estimate, how Welch''s method fixes it, and how to see an instability grow.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 0, 'h', '{"text":"A single spectrum of noise is noisy"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 1, 'p', '{"text":"The squared magnitude of one FFT of a random signal is the **periodogram**. Its scatter does not shrink as the record gets longer: each bin has a standard deviation equal to its mean, however large N is. A longer record gives more bins, not smoother bins."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 2, 'h', '{"text":"Welch''s method"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 3, 'p', '{"text":"Split the record into K segments, window each one, compute each periodogram, and average. Averaging reduces the scatter."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 4, 'eq', '{"text":"\\frac{\\sigma}{\\mu} \\approx \\frac{1}{\\sqrt{K}}","name":"Random error of an averaged PSD"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 5, 'eq', '{"text":"\\mathrm{PSD}[k] = \\frac{2\\,|X[k]|^2}{f_s \\sum_n w[n]^2}","name":"One-sided PSD scaling","caption":"Units of g²/Hz for an acceleration in g"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 6, 'ul', '{"items":["With $f_s = 5$ kHz and 2048-point segments, $\\Delta f = 2.44$ Hz and a 12 s record gives 29 non-overlapping segments, a random error of $1/\\sqrt{29} = 19$ percent.","Overlapping segments by 50 percent with a Hann window recovers most of the information the window throws away.","More segments means shorter segments or a longer record. Resolution and smoothness trade off; you cannot have both from a fixed record."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 7, 'h', '{"text":"From PSD to Grms"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 8, 'p', '{"text":"Parseval turns the PSD back into the rms of the signal."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 9, 'eq', '{"text":"G_{rms} = \\sqrt{\\sum_k \\mathrm{PSD}[k]\\,\\Delta f}","name":"Grms from a PSD"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 10, 'h', '{"text":"The spectrogram: how the spectrum changes in time"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 11, 'p', '{"text":"A **spectrogram** is a sequence of short spectra. Each window has length $T_w$ and resolves $\\Delta f = 1/T_w$, so time and frequency resolution trade off directly: a 20 ms window resolves 50 Hz, a 100 ms window 10 Hz."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'spectral-estimation', 12, 'callout', '{"kind":"key","title":"Why ASRI could not see the instability","text":"A hybrid-motor chamber pressure recorded at about 10 samples per second has a Nyquist limit of 5 Hz, so no spectrogram of the combustion instability could be made. To see chugging at 50 Hz you need at least 500 samples per second and a window of 100 ms or more; to see a 4 kHz screech you need 10 kS/s or more and a window of 20 ms."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'spectral-estimation', 0, 'A single periodogram has scatter equal to its mean; averaging K segments gives $1/\sqrt K$.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'spectral-estimation', 1, 'Grms is the square root of the PSD summed over frequency: Parseval in practice.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'spectral-estimation', 2, 'A spectrogram trades time and frequency resolution: Δf = 1/window length.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'frf-coherence', 'm3', 'Frequency response and coherence', 30, 'Measuring how a structure or sensor responds, and using coherence to know whether to believe it.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 0, 'h', '{"text":"Measure the response with two channels"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 1, 'p', '{"text":"To find how a structure transmits vibration, record the input (a base accelerometer) and the output (a payload accelerometer) at the same time and estimate the frequency response from their spectra."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 2, 'eq', '{"text":"H_1(f) = \\frac{G_{xy}(f)}{G_{xx}(f)}","name":"FRF estimator","caption":"Gxy is the cross-spectrum of input and output, Gxx the input auto-spectrum"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 3, 'h', '{"text":"Coherence"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 4, 'eq', '{"text":"\\gamma^2(f) = \\frac{|G_{xy}|^2}{G_{xx}\\,G_{yy}}, \\qquad 0 \\le \\gamma^2 \\le 1","name":"Coherence function"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 5, 'p', '{"text":"Coherence is the fraction of the output power that is linearly related to the input at each frequency. A value near 1 means the response estimate is trustworthy. A low value means something else is contributing: noise, a second input, or nonlinearity."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 6, 'table', '{"head":["Coherence","Meaning","What to do"],"rows":[["above 0.9","Output is almost entirely explained by the input","Trust the FRF"],["0.5 to 0.9","Noise or a second path","Average more, check the sensors"],["below 0.5","Little linear relation","Do not use the FRF at that frequency"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 7, 'h', '{"text":"How accurate is it?"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 8, 'eq', '{"text":"\\varepsilon\\big[|H|\\big] \\approx \\frac{\\sqrt{1-\\gamma^2}}{|\\gamma|\\sqrt{2K}}","name":"Random error of the gain estimate"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 9, 'p', '{"text":"With $\\gamma^2 = 0.9$ and $K = 50$ averages, the gain error is $\\sqrt{0.1}/(0.949\\sqrt{100}) = 3.3$ percent."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'frf-coherence', 10, 'callout', '{"kind":"tip","title":"Tie it to the vibration course","text":"The transmissibility lab in the Structures, Vibration and Dynamic Environments course computes a response curve. Here you measure one from two accelerometers, and coherence tells you where to believe it."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'frf-coherence', 0, 'The FRF estimate is $H_1 = G_{xy}/G_{xx}$; coherence $\gamma^2$ says how much of the output the input explains.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'frf-coherence', 1, 'Trust an FRF where coherence is above about 0.9, and average more where it is lower.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'frf-coherence', 2, 'The gain''s random error is about $\sqrt{1-\gamma^2}/(|\gamma|\sqrt{2K})$: 3.3 percent for $\gamma^2 = 0.9$ and 50 averages.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm3', 0, 'A record of 4096 samples at 10 kS/s has a bin spacing of:', '["0.24 Hz","2.44 Hz","24.4 Hz","244 Hz"]', 1, '$10\,000/4096 = 2.44$ Hz.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm3', 1, 'Why does a longer record not smooth a single periodogram?', '["It does, linearly","Each bin keeps a scatter equal to its mean; a longer record only adds bins","FFTs are exact","The window removes it"]', 1, 'The periodogram''s relative scatter is about 1 regardless of N, so only averaging reduces it.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm3', 2, 'A 12 s record at 5 kS/s is cut into 2048-point segments. The number of non-overlapping segments is about:', '["3","14","29","290"]', 2, '60 000 / 2048 = 29.3.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm3', 3, 'What does a coherence of 0.3 at 800 Hz tell you?', '["The FRF there is accurate","Little of the output is linearly related to the input there; do not trust the FRF","The sensors are saturated","800 Hz is a resonance"]', 1, 'Low coherence means noise, a second input or nonlinearity dominates, so the FRF estimate is unreliable.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('signals-dsp-estimation', 'm4', 'Noise, least squares and recursive estimation', 'Random errors, how to combine measurements optimally, and the filters that update an estimate as data arrive.', 3);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'noise-probability', 'm4', 'Noise and probability', 30, 'Mean, variance, the Gaussian, averaging, covariance and what breaks when noise is not white.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 0, 'h', '{"text":"Describing a random error"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 1, 'p', '{"text":"A noisy measurement is a random variable. Two numbers summarise most of what matters: the **mean** (its bias if it differs from the truth) and the **variance** $\\sigma^2$ (its scatter), with $\\sigma$ the standard deviation."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 2, 'eq', '{"text":"p(x) = \\frac{1}{\\sigma\\sqrt{2\\pi}}\\,e^{-(x-\\mu)^2/(2\\sigma^2)}","name":"The Gaussian distribution"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 3, 'table', '{"head":["Interval","Probability (Gaussian)"],"rows":[["±1σ","68 percent"],["±2σ","95 percent"],["±3σ","99.7 percent"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 4, 'p', '{"text":"The Gaussian appears everywhere because sums of many small independent effects tend toward it, and because a sum or a product of Gaussians stays Gaussian. That second property is what makes the Kalman filter tractable."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 5, 'h', '{"text":"Averaging"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 6, 'eq', '{"text":"\\sigma_{mean} = \\frac{\\sigma}{\\sqrt{N}}","name":"Standard error of an average of N independent samples"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 7, 'p', '{"text":"Averaging 100 independent readings of a 1.57 mg-rms accelerometer gives 0.157 mg. This works only if the noise is **white**, meaning each sample is independent. A bias, a slow drift or noise correlated from sample to sample does not average away."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 8, 'h', '{"text":"Combining two measurements"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 9, 'p', '{"text":"Two sensors measure the same thing with standard deviations $\\sigma_1$ and $\\sigma_2$. The best linear combination weights each by the inverse of its variance."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 10, 'eq', '{"text":"w_i = \\frac{1/\\sigma_i^2}{\\sum_j 1/\\sigma_j^2}, \\qquad \\frac{1}{\\sigma_{comb}^2} = \\sum_i\\frac{1}{\\sigma_i^2}","name":"Inverse-variance weighting"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 11, 'p', '{"text":"With $\\sigma_1 = 2$ and $\\sigma_2 = 1$, the weights are 0.2 and 0.8 and the combined standard deviation is 0.894, better than either sensor."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 12, 'h', '{"text":"Covariance"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 13, 'p', '{"text":"For several quantities, the **covariance matrix** holds the variances on its diagonal and the way the errors move together off it. The Kalman filter carries this matrix along with the estimate."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'noise-probability', 14, 'callout', '{"kind":"warn","title":"Check whiteness before trusting √N","text":"Log a stationary record and compute its Allan deviation (see the IMU course). If the deviation stops falling as you average longer, drift has taken over and more averaging will not help."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'noise-probability', 0, 'A Gaussian is described by its mean and variance; ±3σ holds 99.7 percent.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'noise-probability', 1, 'Averaging N independent samples reduces the noise by $\sqrt N$, but not bias or drift.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'noise-probability', 2, 'Combine measurements by inverse-variance weighting; the result beats the best single sensor.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'noise-probability', 0, 'Kalman and Bayesian Filters in Python, ch. 4 (Gaussian probabilities)', 'Labbé', 'https://github.com/rlabbe/Kalman-and-Bayesian-Filters-in-Python', 'Local copy: study library');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'least-squares', 'm4', 'Least squares', 30, 'Fitting a model to noisy data: the normal equations, weights, and the calibration and drift problems they solve.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 0, 'h', '{"text":"The best line through noisy points"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 1, 'p', '{"text":"You have measurements $b$ that you expect to follow a linear model $b \\approx A\\,x$ with unknown parameters $x$. **Least squares** chooses $x$ to minimise the sum of the squared errors."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 2, 'eq', '{"text":"\\hat x = (A^{T}A)^{-1}A^{T}b","name":"Normal equations"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 3, 'eq', '{"text":"\\hat x = (A^{T}WA)^{-1}A^{T}Wb, \\quad W = \\mathrm{diag}(1/\\sigma_i^2)","name":"Weighted least squares","caption":"Noisier points count for less"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 4, 'h', '{"text":"A worked example"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 5, 'p', '{"text":"Fit a line $y = mt + c$ to the points (0, 1.1), (1, 2.9), (2, 5.2). The least-squares answer is $m = 2.05$ and $c = 1.017$. No line passes through all three, and this one minimises the total squared error."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 6, 'h', '{"text":"Where you will use it"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 7, 'ul', '{"items":["**Sensor calibration:** the six-position accelerometer test is a least-squares fit of the scale and bias to readings at known gravity.","**Thermal drift:** fit bias against temperature with a low-order polynomial.","**Velocity from altitude:** the slope of a short window of altitude samples, fitted by least squares, is a velocity estimate with less noise than differencing two samples.","**Curve fitting to a decay:** the log of a decaying vibration envelope is a straight line whose slope gives the damping."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 8, 'callout', '{"kind":"key","title":"Least squares is the maximum-likelihood answer for Gaussian noise","text":"That is why it is the default. It also shows what a Kalman filter is: a recursive form of weighted least squares that updates the answer one measurement at a time."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'least-squares', 9, 'callout', '{"kind":"warn","title":"Outliers dominate","text":"Squaring makes one wild point count as much as many ordinary ones. Remove saturated samples and spikes first, or use a robust fit."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'least-squares', 0, 'Least squares gives $\hat x = (A^TA)^{-1}A^Tb$; weighting by $1/\sigma^2$ favours the quieter data.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'least-squares', 1, 'Calibration, thermal drift and velocity-from-position are all least-squares fits.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'least-squares', 2, 'A Kalman filter is recursive weighted least squares.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'least-squares', 0, 'Kalman and Bayesian Filters in Python, ch. 3 (least squares filters)', 'Labbé', 'https://github.com/rlabbe/Kalman-and-Bayesian-Filters-in-Python', 'Local copy: study library');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'recursive-estimation', 'm4', 'Recursive estimation: the g-h filter', 35, 'Updating an estimate one measurement at a time, with a prediction and a gain, before you meet the Kalman filter.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 0, 'h', '{"text":"Predict, then correct"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 1, 'p', '{"text":"You rarely have the whole record before you need an answer. A **recursive** estimator keeps a current estimate, predicts where the quantity will be at the next sample, and corrects the prediction with the new measurement."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 2, 'eq', '{"text":"\\hat x_k = \\hat x_k^{-} + K\\,(z_k - \\hat x_k^{-})","name":"Correction step","caption":"z is the measurement and the bracket is the residual or innovation"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 3, 'p', '{"text":"The gain $K$ between 0 and 1 sets the balance. $K = 0$ ignores the measurement; $K = 1$ believes it completely and passes its noise through. A constant gain is the exponential average from the filter module."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 4, 'h', '{"text":"The g-h filter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 5, 'p', '{"text":"For something that moves with a roughly constant velocity, track two quantities, position and velocity, with two gains."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 6, 'eq', '{"text":"\\hat x^{-} = \\hat x + \\dot{\\hat x}\\,\\Delta t, \\qquad \\hat x \\leftarrow \\hat x^{-} + g\\,(z - \\hat x^{-}), \\qquad \\dot{\\hat x} \\leftarrow \\dot{\\hat x} + h\\,\\frac{z - \\hat x^{-}}{\\Delta t}","name":"g-h filter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 7, 'ul', '{"items":["A large $g$ and $h$ follow changes quickly and let more noise through.","A small $g$ and $h$ smooth heavily and lag behind real changes, which is a bias if the target accelerates.","The gains are a compromise that you set by hand. The Kalman filter computes them from the noise levels."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 8, 'h', '{"text":"Bayesian view"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 9, 'p', '{"text":"The same idea in probability terms: before the measurement you hold a belief about the state (the prior). The measurement, with its own uncertainty, updates it by Bayes'' rule to a narrower belief (the posterior). Repeat for every sample."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'recursive-estimation', 10, 'callout', '{"kind":"key","title":"Every Kalman filter is a g-h filter with computed gains","text":"When you understand the g-h filter, the Kalman equations are only a principled way to choose its gains from the noise levels and to carry the uncertainty along."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'recursive-estimation', 0, 'A recursive estimator predicts, then corrects by gain times the residual.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'recursive-estimation', 1, 'A g-h filter tracks position and velocity with two fixed gains; large gains follow quickly and pass noise.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'recursive-estimation', 2, 'Bayes'' rule updates a belief with each measurement; the Kalman filter is the Gaussian case.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'recursive-estimation', 0, 'Kalman and Bayesian Filters in Python, ch. 1 (the g-h filter) and ch. 2 (discrete Bayes)', 'Labbé', 'https://github.com/rlabbe/Kalman-and-Bayesian-Filters-in-Python', 'Local copy: study library');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm4', 0, 'Averaging 100 independent samples of 1.57 mg rms noise gives:', '["15.7 mg","1.57 mg","0.157 mg","0.0157 mg"]', 2, '$1.57/\sqrt{100} = 0.157$ mg.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm4', 1, 'Two sensors have σ = 2 and σ = 1. Optimal inverse-variance weights are:', '["0.5 and 0.5","0.2 and 0.8","0.33 and 0.67","0.1 and 0.9"]', 1, '$(1/4)/(1/4 + 1) = 0.2$ and $0.8$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm4', 2, 'Why does averaging fail on a drifting sensor?', '["Drift is random white noise","Drift is correlated between samples, so it does not average out","Averages are always exact","Drift is too small"]', 1, 'Averaging helps only with independent noise; slow drift is correlated in time and stays.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm4', 3, 'In a recursive estimator with gain K = 0, the measurement is:', '["Fully trusted","Ignored","Doubled","Squared"]', 1, 'K scales the correction; at 0 the estimate never changes.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('signals-dsp-estimation', 'm5', 'Kalman filters', 'The scalar and multi-state filters, tuning, consistency checks and the failures to watch for.', 4);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'kalman-1d', 'm5', 'The one-dimensional Kalman filter', 35, 'Predict and update with computed gains, a three-step worked example, and the steady state.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 0, 'h', '{"text":"Track the estimate and its uncertainty"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 1, 'p', '{"text":"The Kalman filter carries two numbers: the estimate $\\hat x$ and its variance $P$. Each step has a prediction and an update."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 2, 'ol', '{"items":["**Predict:** the state is assumed constant, so $\\hat x^{-} = \\hat x$, but our confidence falls: $P^{-} = P + Q$. Here $Q$ is the **process noise**, the amount the true value can wander per step.","**Gain:** $K = P^{-}/(P^{-} + R)$, where $R$ is the measurement noise variance. A noisy measurement (large $R$) gives a small $K$.","**Update:** $\\hat x = \\hat x^{-} + K(z - \\hat x^{-})$ and $P = (1 - K)P^{-}$. The uncertainty always shrinks after a measurement."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 3, 'h', '{"text":"Worked example"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 4, 'p', '{"text":"Start with $\\hat x = 0$, $P = 1$, $Q = 0.01$ and $R = 0.25$. Three measurements: 1.1, 0.9, 1.05."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 5, 'table', '{"head":["Step","Measurement","Gain K","Estimate","Variance P"],"rows":[["1","1.10","0.802","0.882","0.200"],["2","0.90","0.457","0.890","0.114"],["3","1.05","0.332","0.943","0.083"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 6, 'p', '{"text":"The first measurement is trusted heavily (K = 0.80) because the initial estimate was very uncertain. As the variance falls, the gain falls and each new measurement changes the estimate less."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 7, 'h', '{"text":"Steady state"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 8, 'p', '{"text":"With constant $Q$ and $R$ the gain settles. Here it converges to $K = 0.181$ and $P = 0.045$, which is an exponential filter with a time constant of about 5 samples. A larger $Q$ (a quantity that wanders more) raises the steady gain and follows changes faster; a larger $R$ lowers it and smooths more."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-1d', 9, 'callout', '{"kind":"key","title":"Q and R are the only knobs","text":"Everything the filter does follows from the ratio of the process noise to the measurement noise. Set R from the sensor datasheet or a stationary test, and set Q from how much the quantity can really change between samples."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'kalman-1d', 0, 'Predict: $P^- = P + Q$. Update: $K = P^-/(P^- + R)$, $\hat x = \hat x^- + K(z - \hat x^-)$, $P = (1-K)P^-$.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'kalman-1d', 1, 'The gain starts high when the estimate is uncertain and settles to a steady value set by Q/R.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'kalman-1d', 2, 'A large Q follows changes quickly; a large R smooths heavily.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'kalman-1d', 0, 'Kalman and Bayesian Filters in Python, ch. 5 (one-dimensional Kalman filters)', 'Labbé', 'https://github.com/rlabbe/Kalman-and-Bayesian-Filters-in-Python', 'Local copy: study library');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'kalman-multi', 'm5', 'Multi-state Kalman filters', 40, 'State, transition and measurement matrices, a barometer and accelerometer altitude filter, and the numbers that come out.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 0, 'h', '{"text":"Matrices instead of numbers"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 1, 'p', '{"text":"For several states, the estimate becomes a vector $\\mathbf{x}$ and the variance a covariance matrix $\\mathbf{P}$."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 2, 'eq', '{"text":"\\mathbf{x}^{-} = F\\mathbf{x} + B\\,u, \\qquad P^{-} = F P F^{T} + Q","name":"Predict"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 3, 'eq', '{"text":"S = H P^{-} H^{T} + R, \\quad K = P^{-}H^{T}S^{-1}, \\quad \\mathbf{x} = \\mathbf{x}^{-} + K\\,(z - H\\mathbf{x}^{-}), \\quad P = (I - KH)P^{-}","name":"Update"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 4, 'h', '{"text":"An altitude filter: barometer plus accelerometer"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 5, 'p', '{"text":"A rocket''s vertical state is altitude and vertical velocity. The IMU supplies acceleration $a$ (after removing gravity), which drives the prediction; the barometer supplies a noisy altitude, which corrects it."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 6, 'eq', '{"text":"F = \\begin{pmatrix}1 & \\Delta t\\\\ 0 & 1\\end{pmatrix}, \\quad B = \\begin{pmatrix}\\tfrac12\\Delta t^2\\\\ \\Delta t\\end{pmatrix}, \\quad H = \\begin{pmatrix}1 & 0\\end{pmatrix}","name":"Altitude and velocity model"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 7, 'eq', '{"text":"Q = \\sigma_a^2\\begin{pmatrix}\\tfrac14\\Delta t^4 & \\tfrac12\\Delta t^3\\\\ \\tfrac12\\Delta t^3 & \\Delta t^2\\end{pmatrix}, \\qquad R = \\sigma_h^2","name":"Process and measurement noise"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 8, 'p', '{"text":"With $\\Delta t = 0.1$ s, accelerometer noise $\\sigma_a = 0.5$ m/s² and barometer noise $\\sigma_h = 2$ m, the steady-state gain is $K = (0.068,\\ 0.024)^T$. The filter''s own uncertainty settles at 0.52 m in altitude and 0.26 m/s in velocity, better than the barometer''s 2 m, because the accelerometer carries the estimate between baro readings."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 9, 'ul', '{"items":["At start-up, with an uncertain initial state (say $P = \\mathrm{diag}(100, 25)$), the first altitude gain is 0.96: the filter nearly adopts the first barometer reading.","Run the prediction at the IMU rate (1 kHz) and the update at the barometer rate (50 Hz or so). Between baro samples, $P$ grows; at each update it shrinks.","Keep $P$ symmetric and positive. The Joseph form $P = (I-KH)P^{-}(I-KH)^T + KRK^T$ preserves that in finite precision."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'kalman-multi', 10, 'callout', '{"kind":"tip","title":"Cross-check with the course on the IMU","text":"The IMU course showed that a 0.05 m/s² accelerometer bias gives a 40 m error in 40 s with no aid. This filter bounds that error by tying the estimate to the barometer."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'kalman-multi', 0, 'Predict with $F$ and $Q$, update with $H$, $R$ and the gain $K = P^-H^TS^{-1}$.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'kalman-multi', 1, 'An accelerometer-driven, baro-corrected filter is more accurate than the barometer alone: 0.52 m against 2 m in the example.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'kalman-multi', 2, 'Predict at the IMU rate, update at the sensor rate, and keep P symmetric.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('signals-dsp-estimation', 'kalman-multi', 0, 'Kalman and Bayesian Filters in Python, ch. 6 to 8 (multivariate filters, Kalman math, design)', 'Labbé', 'https://github.com/rlabbe/Kalman-and-Bayesian-Filters-in-Python', 'Local copy: study library');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'fusion-practice', 'm5', 'Tuning, checking and failure modes', 35, 'Innovations as the health check, outliers and saturation, sensor delay, bias states and when to leave the linear filter behind.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 0, 'h', '{"text":"The innovation is the filter''s report card"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 1, 'p', '{"text":"The **innovation** is the gap between a measurement and what the filter predicted for it, with predicted variance $S$. If the model and noise levels are right, innovations are zero-mean, white and have variance $S$."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 2, 'eq', '{"text":"\\mathrm{NIS} = \\nu^{T}S^{-1}\\nu \\sim \\chi^2_m","name":"Normalised innovation squared","caption":"m is the number of measurement components"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 3, 'ul', '{"items":["For one measurement, NIS should fall below 3.84 about 95 percent of the time and below 6.63 about 99 percent of the time.","NIS mostly **above** that: noise is underestimated or the model is wrong, so raise R or Q.","NIS always far **below**: noise is overestimated and the filter is slower and noisier than it needs to be."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 4, 'h', '{"text":"Failure modes"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 5, 'table', '{"head":["Failure","Cause","Defence"],"rows":[["A wild measurement pulls the estimate","Barometer spike near Mach 1, GPS glitch","Gate: reject a measurement whose innovation exceeds about 3 standard deviations"],["Clipped accelerometer fed in as truth","Sensor beyond its range","Treat saturated samples as missing and let covariance grow"],["A late measurement applied as current","Barometer delay, GPS latency","Time-stamp every measurement and apply it at its own time"],["Estimate lags a real acceleration","Q too small","Raise Q, or add an acceleration state"],["Estimate diverges","Bad initial P, nonlinear model, numerical loss of symmetry","Start with a large P, use the Joseph form, switch to an extended filter"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 6, 'p', '{"text":"The delay one is worth a number: a barometer reading that is 50 ms old at 300 m/s is 15 m out of date. Applied as current, it is a 15 m error that no tuning removes."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 7, 'h', '{"text":"Add a bias state"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 8, 'p', '{"text":"If the accelerometer has an unknown constant bias, add it to the state vector. The barometer makes it observable: a bias shows up as a steady disagreement between the predicted and measured altitude, and the filter learns to subtract it."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 9, 'h', '{"text":"When linear is not enough"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 10, 'p', '{"text":"Attitude from gyros is nonlinear in the quaternion, so the linear Kalman equations do not apply directly. The **extended** Kalman filter linearises at each step, and the **unscented** filter propagates sample points. Both follow the same predict, gain and update structure you have learned."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'fusion-practice', 11, 'callout', '{"kind":"key","title":"A complementary filter is a Kalman filter with a fixed gain","text":"The tilt-correction filter in the IMU course is the steady-state limit of a Kalman filter with constant Q and R. The Kalman version adapts: it trusts the accelerometer more as the uncertainty grows and less when the rocket is accelerating."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'fusion-practice', 0, 'Check the filter with its innovations: NIS should stay below 3.84 about 95 percent of the time.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'fusion-practice', 1, 'Gate outliers, treat saturated samples as missing and time-stamp every measurement; a 50 ms delay at 300 m/s is a 15 m error.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'fusion-practice', 2, 'Add a bias state for a constant sensor bias; use an extended filter for nonlinear problems such as attitude.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm5', 0, 'In a scalar Kalman filter, a very large measurement noise R makes the gain:', '["Large","Small, so the measurement barely changes the estimate","Zero always","Negative"]', 1, '$K = P^-/(P^- + R) \to 0$ as $R$ grows.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm5', 1, 'The filter''s uncertainty after an update compared with before is:', '["Larger","The same","Smaller","Undefined"]', 2, '$P = (1 - K)P^-$, with $0 \le K \le 1$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm5', 2, 'For a one-component measurement, what NIS threshold is exceeded only about 5 percent of the time?', '["1.0","3.84","10","100"]', 1, 'The 95th percentile of a chi-squared distribution with one degree of freedom is 3.84.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm5', 3, 'A barometer reading 50 ms old is applied as current to a rocket at 300 m/s. The position error is:', '["1.5 m","15 m","150 m","0 m"]', 1, '300 m/s × 0.05 s = 15 m.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('signals-dsp-estimation', 'm6', 'Capstone: a processing pipeline', 'Specify the filters, spectra and estimators for a vibration channel and an altitude estimate, with every number traced.', 5);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('signals-dsp-estimation', 'pipeline', 'm6', 'Capstone: specify a flight-data processing pipeline', 60, 'Decimation filter, PSD plan and altitude filter for a Phoenix-class instrument, each with its numbers and its checks.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 0, 'h', '{"text":"The brief"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 1, 'p', '{"text":"A vibration accelerometer is sampled at 25 kS/s and must be analysed from 20 to 2 000 Hz. An IMU delivers vertical acceleration at 1 kHz and a barometer delivers altitude at 50 Hz. Specify the processing, with every number traced to a lesson."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 2, 'h', '{"text":"1. Vibration channel: decimate from 25 kS/s to 5 kS/s"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 3, 'ul', '{"items":["Keep 0 to 2 kHz; aliases into that band come from above 5 − 2 = 3 kHz at the new rate. The transition band is 2 to 3 kHz, 1 kHz wide.","Hamming FIR: $N \\approx 3.3 \\times 25\\,000/1000 = 83$ taps, about 53 dB of rejection, delay 41 samples = 1.64 ms.","A polyphase implementation needs 83 multiply-accumulates per output at 5 kS/s, about 0.4 million per second per channel and 1.2 million for three channels. Trivial for any microcontroller."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 4, 'h', '{"text":"2. PSD and Grms"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 5, 'ul', '{"items":["Hann window, 2048-point segments at 5 kS/s: $\\Delta f = 2.44$ Hz.","A 12 s record has 29 non-overlapping segments, so a random error of $1/\\sqrt{29} = 19$ percent. Overlapping 50 percent improves it; a longer record improves it further.","Grms is the square root of the PSD summed over 20 to 2 000 Hz. Compare with NASA''s 10 and 12.7 Grms test levels, and report resolution, window and number of averages with every plot."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 6, 'h', '{"text":"3. Altitude and velocity"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 7, 'ul', '{"items":["Predict at 1 kHz with the accelerometer; update at 50 Hz with the barometer. $\\sigma_a = 0.5$ m/s², $\\sigma_h = 2$ m.","Gate the barometer on a 3σ innovation test and reject it entirely near Mach 1, where static-pressure readings are unreliable.","Time-stamp the barometer and apply it at its own time; a 50 ms delay at 300 m/s would otherwise be a 15 m error.","Add an accelerometer-bias state, since the barometer makes it observable."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 8, 'h', '{"text":"4. Checks to run on every flight log"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 9, 'table', '{"head":["Check","Pass condition"],"rows":[["Anti-alias: sweep test of the decimator","Output above 3 kHz at least 53 dB down"],["PSD: Parseval","Grms from the samples equals Grms from the PSD within 1 percent"],["Altitude filter innovations","NIS below 3.84 about 95 percent of the time"],["Gate","Rejected barometer samples cluster near transonic flight, not at random"],["Coherence between base and payload accelerometers","Above 0.9 where the FRF is used"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('signals-dsp-estimation', 'pipeline', 10, 'callout', '{"kind":"key","title":"Plan the analysis before you build the recorder","text":"The sample rates, record lengths and channels in the recorder were set by what these steps need. If you decide the analysis afterwards, you may find the recording cannot support it."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'pipeline', 0, 'A complete pipeline has a decimation filter, a PSD plan with a stated error, and a Kalman filter with gating and time-alignment.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'pipeline', 1, 'Every stage has a check that can be run on the log: a sweep, Parseval, NIS and coherence.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('signals-dsp-estimation', 'pipeline', 2, 'Decide the analysis first, then the recorder''s sample rates and record lengths.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm6', 0, 'How many Hamming FIR taps decimate 25 kS/s to 5 kS/s with a 1 kHz transition band?', '["16","40","83","250"]', 2, '$3.3 \times 25\,000 / 1000 = 82.5$, so 83.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm6', 1, 'A 12 s record at 5 kS/s with 2048-point segments gives a PSD random error of about:', '["2 percent","19 percent","50 percent","100 percent"]', 1, '$1/\sqrt{29} = 0.19$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('signals-dsp-estimation', 'm6', 2, 'Which check confirms a PSD has the right scaling?', '["Parseval: Grms from the samples equals Grms from the PSD","The sample rate is a power of two","The window is rectangular","The FFT is fast"]', 0, 'Parseval says the power must match between the time and frequency domains.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 0, 'rms', 'm1', 'Root-mean-square value. For a sinusoid of peak $A$ it is $A/\sqrt2$.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 1, 'Decibel', 'm1', 'Ten times the log of a power ratio, or twenty times the log of an amplitude ratio.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 2, 'Impulse response', 'm1', 'The output of an LTI system for a single sharp input; it fully describes the system.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 3, 'Convolution', 'm1', 'The operation that gives the output of an LTI system as the input weighted by its impulse response.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 4, 'Alias', 'm1', 'A frequency above half the sample rate that appears as a lower one after sampling.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 5, 'LSB', 'm1', 'Least significant bit: the step size of a converter, full scale divided by 2^N.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 6, 'ENOB', 'm1', 'Effective number of bits: the resolution implied by a converter''s measured SINAD.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 7, 'FIR filter', 'm2', 'Finite impulse response filter: a weighted sum of recent inputs, always stable, linear phase if symmetric.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 8, 'IIR filter', 'm2', 'Infinite impulse response filter: uses feedback of past outputs; sharp with few coefficients, nonlinear phase.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 9, 'Bilinear transform', 'm2', 'A mapping from an analog filter to a digital one that warps the frequency axis.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 10, 'Biquad', 'm2', 'A second-order IIR section; high-order filters are built as a cascade of them.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 11, 'Decimation', 'm2', 'Lowering the sample rate by low-pass filtering and then keeping every Mth sample.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 12, 'Group delay', 'm2', 'The time a filter delays a signal; (N−1)/2 samples for a symmetric FIR filter.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 13, 'DFT', 'm3', 'Discrete Fourier transform: N samples to N frequency bins.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 14, 'Leakage', 'm3', 'Spreading of a tone''s energy into neighbouring bins when it does not fit a whole number of cycles in the record.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 15, 'Window', 'm3', 'A taper applied to a record before the DFT to reduce leakage.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 16, 'Periodogram', 'm3', 'The squared magnitude of one FFT; an estimate whose scatter does not fall as the record lengthens.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 17, 'Welch''s method', 'm3', 'PSD estimation by averaging windowed, overlapping segment periodograms.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 18, 'Spectrogram', 'm3', 'A sequence of short spectra showing how frequency content changes with time.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 19, 'Coherence', 'm3', 'The fraction of output power linearly related to the input at each frequency, between 0 and 1.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 20, 'White noise', 'm4', 'Noise whose samples are independent, so averaging reduces it as 1/√N.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 21, 'Covariance matrix', 'm4', 'A matrix of variances and cross-variances describing the uncertainty of several quantities.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 22, 'Least squares', 'm4', 'Choosing parameters to minimise the sum of squared errors between a model and data.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 23, 'Process noise (Q)', 'm5', 'The amount a state is allowed to wander between steps in a Kalman filter.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 24, 'Measurement noise (R)', 'm5', 'The variance of a sensor''s measurement in a Kalman filter.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 25, 'Innovation', 'm5', 'The difference between a measurement and the filter''s prediction of it.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('signals-dsp-estimation', 26, 'NIS', 'm5', 'Normalised innovation squared: a statistic that should follow a chi-squared distribution when the filter is consistent.');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('signals-dsp-estimation', 0, 'The Scientist and Engineer''s Guide to Digital Signal Processing (Smith)', 'Open textbook', 'https://www.dspguide.com/', 'Local chapters in the study library; ch. 2 to 21 support modules 1 to 4');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('signals-dsp-estimation', 1, 'Kalman and Bayesian Filters in Python (Labbé)', 'Open textbook', 'https://github.com/rlabbe/Kalman-and-Bayesian-Filters-in-Python', 'Local copy in the study library; ch. 1 to 8 support module 5');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('signals-dsp-estimation', 2, 'Discrete-Time Signal Processing (Oppenheim and Schafer)', 'Prentice Hall', NULL, 'The standard textbook behind the MIT lectures used here');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('signals-dsp-estimation', 3, 'Random Data: Analysis and Measurement Procedures (Bendat and Piersol)', 'Wiley', NULL, 'Source of the coherence and PSD error formulas');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('signals-dsp-estimation', 4, 'Antialiasing filter circuit design for single-ended ADC input (SBAA282)', 'Texas Instruments', NULL, 'Study library #19');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('signals-dsp-estimation', 5, 'Anti-aliasing filter design for a 100 kHz DAQ signal chain (SBAA655)', 'Texas Instruments', NULL, 'Study library #20');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('signals-dsp-estimation', 6, 'MIT RES.6-008 Digital Signal Processing, 1975 (Oppenheim)', 'MIT OpenCourseWare', 'https://ocw.mit.edu/courses/res-6-008-digital-signal-processing-spring-2011/', 'Lecture series behind the filter and DFT lessons');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('signals-dsp-estimation', 7, 'Digital Signal Processing (Prof. S. C. Dutta Roy)', 'NPTEL, IIT Delhi', 'https://nptel.ac.in/', 'Search the NPTEL catalogue for the course');
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'sine-rms', 'm1', 'Sine rms', 'rms $= A/\sqrt2$. A 10 g peak sine is **7.07 g** rms.', 0);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'db', 'm1', 'Decibel quick values', 'Amplitude ratio 2 is **6 dB**, 10 is **20 dB**, 1 000 is **60 dB**; −3 dB is half power.', 1);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'alias', 'm1', 'Alias frequency', '$f_{alias} = |f - kf_s|$. **7 kHz at 10 kS/s appears at 3 kHz.**', 2);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'quant', 'm1', 'Quantization', '$\Delta = FS/2^N$, $q_{rms} = \Delta/\sqrt{12}$, SNR $\approx 6.02N + 1.76$ dB: **98 dB at 16 bits**.', 3);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'fir-n', 'm2', 'FIR length', 'Hamming: $N \approx 3.3f_s/\Delta f$ (53 dB). Blackman: $5.5f_s/\Delta f$ (74 dB). Delay **(N−1)/2** samples.', 4);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'warp', 'm2', 'Bilinear pre-warp', '$\Omega = 2f_s\tan(\pi f/f_s)$. **2 kHz at 10 kS/s is 14 531 rad/s**, not 12 566.', 5);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'df', 'm3', 'Bin spacing', '$\Delta f = f_s/N = 1/T$. **4096 points at 10 kS/s is 2.44 Hz.**', 6);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'windows', 'm3', 'Window choice', 'Rectangular 3.9 dB scalloping, **Hann 1.4 dB**, flat-top under 0.01 dB.', 7);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'welch', 'm3', 'Welch error', '$\sigma/\mu \approx 1/\sqrt K$: **29 segments is 19 percent**, 50 is 14 percent.', 8);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'spectrogram', 'm3', 'Spectrogram resolution', '$\Delta f = 1/T_w$: **20 ms resolves 50 Hz**, 100 ms resolves 10 Hz.', 9);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'coherence', 'm3', 'FRF gain error', '$\sqrt{1-\gamma^2}/(|\gamma|\sqrt{2K})$: **3.3 percent** at $\gamma^2 = 0.9$, $K = 50$.', 10);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'avg', 'm4', 'Averaging', '$\sigma/\sqrt N$ for white noise only. **100 samples cuts noise by 10.**', 11);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'weights', 'm4', 'Inverse-variance weights', '$w_i \propto 1/\sigma_i^2$. σ of 2 and 1 gives weights **0.2 and 0.8**, σ combined **0.894**.', 12);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'kalman1d', 'm5', 'Scalar Kalman filter', '$P^- = P+Q$; $K = P^-/(P^-+R)$; $\hat x = \hat x^- + K(z-\hat x^-)$; $P = (1-K)P^-$.', 13);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('signals-dsp-estimation', 'nis', 'm5', 'NIS thresholds', 'One measurement: **3.84** (95 percent) and **6.63** (99 percent).', 14);
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('signals-dsp-estimation', 'py-fir', 'm2', 'Design and apply a Hamming FIR filter', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('signals-dsp-estimation', 'py-welch', 'm3', 'Welch PSD, Grms and a spectrogram', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('signals-dsp-estimation', 'py-kalman', 'm5', 'Altitude filter: accelerometer predicts, barometer corrects', 'python', 'import numpy as np
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('signals-dsp-estimation', 'm1-problems', 'm1', 'Signals and sampling problems', 'rms, decibels, aliasing and quantization.', 'problems', 0);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm1-problems', 'm1-problems-1', 0, 'numeric', 1, 'A vibration sine has a 10 g peak. What is its rms value?', NULL, '$10/\sqrt2 = 7.07$ g.', NULL, NULL, 7.07, 0.01, 'g');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm1-problems', 'm1-problems-2', 1, 'numeric', 1, 'A gain of 1 000 in amplitude is how many decibels?', NULL, '$20\log_{10}1000 = 60$ dB.', NULL, NULL, 60, 0.02, 'dB');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm1-problems', 'm1-problems-3', 2, 'numeric', 1, 'An RC low-pass uses R = 10 kΩ and C = 16 nF. What is its cutoff frequency?', NULL, '$f_c = 1/(2\pi RC) = 1/(2\pi\times10^4\times16\times10^{-9}) = 995$ Hz.', NULL, NULL, 995, 0.01, 'Hz');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm1-problems', 'm1-problems-4', 3, 'numeric', 1, 'A 7 kHz tone is sampled at 10 kS/s with no filter. At what frequency does it appear?', NULL, '$|7000 - 10000| = 3000$ Hz.', NULL, NULL, 3000, 0.02, 'Hz');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm1-problems', 'm1-problems-5', 4, 'numeric', 1, 'What is the ideal quantization SNR of a 16-bit converter?', NULL, '$6.02\times16 + 1.76 = 98.08$ dB.', NULL, NULL, 98.1, 0.01, 'dB');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm1-problems', 'm1-problems-6', 5, 'numeric', 2, 'A ±16 g accelerometer is read by a 16-bit converter. What is the LSB in mg?', NULL, '$32\,\mathrm{g}/65\,536 = 0.488$ mg.', NULL, NULL, 0.488, 0.01, 'mg');
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('signals-dsp-estimation', 'm2-problems', 'm2', 'Filter problems', 'Taps, delay, pre-warping and time constants.', 'problems', 1);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm2-problems', 'm2-problems-1', 0, 'numeric', 1, 'A Hamming FIR filter needs a 500 Hz transition at 10 kS/s. How many taps?', NULL, '$N \approx 3.3\times10\,000/500 = 66$.', NULL, NULL, 66, 0.02, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm2-problems', 'm2-problems-2', 1, 'numeric', 2, 'What is the delay of a symmetric 66-tap FIR filter at 10 kS/s, in milliseconds?', NULL, '$(66-1)/2 = 32.5$ samples $= 3.25$ ms.', NULL, NULL, 3.25, 0.02, 'ms');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm2-problems', 'm2-problems-3', 2, 'numeric', 1, 'An 11-sample moving average runs at 1 kHz. What is its delay in milliseconds?', NULL, '$(11-1)/2 = 5$ samples $= 5$ ms.', NULL, NULL, 5, 0.02, 'ms');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm2-problems', 'm2-problems-4', 3, 'numeric', 3, 'Pre-warp a 2 kHz cutoff for a bilinear design at 10 kS/s. What analog frequency, in rad/s, do you design for?', NULL, '$2\times10\,000\tan(0.2\pi) = 14\,531$ rad/s.', NULL, NULL, 14531, 0.01, 'rad/s');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm2-problems', 'm2-problems-5', 4, 'numeric', 2, 'An exponential filter at 1 kHz has a 50 ms time constant. What is α = 1 − exp(−Δt/τ)?', NULL, '$1 - e^{-0.001/0.05} = 0.0198$.', NULL, NULL, 0.0198, 0.02, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm2-problems', 'm2-problems-6', 5, 'mcq', 2, 'You need to preserve the shape of a shock pulse. Which filter type?', NULL, 'Linear phase delays every frequency equally, so the waveform keeps its shape; an IIR distorts it.', '["A high-order Butterworth IIR","A symmetric (linear-phase) FIR filter","A notch filter","Any, shape never changes"]', 1, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('signals-dsp-estimation', 'm3-problems', 'm3', 'Spectrum problems', 'Bin spacing, FFT cost, Welch error, spectrogram and coherence.', 'problems', 2);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm3-problems', 'm3-problems-1', 0, 'numeric', 1, 'A 4096-point FFT is taken at 10 kS/s. What is the bin spacing?', NULL, '$10\,000/4096 = 2.44$ Hz.', NULL, NULL, 2.44, 0.01, 'Hz');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm3-problems', 'm3-problems-2', 1, 'numeric', 2, 'How many times fewer operations does a 4096-point FFT need than a direct DFT (N² over N·log₂N)?', NULL, '$4096^2/(4096\times12) = 341$.', NULL, NULL, 341, 0.01, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm3-problems', 'm3-problems-3', 2, 'numeric', 1, 'A 12 s record at 5 kS/s is cut into 2048-point segments. How many segments (no overlap)?', NULL, '$60\,000/2048 = 29.3$, so 29.', NULL, NULL, 29, 0.02, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm3-problems', 'm3-problems-4', 3, 'numeric', 2, 'With 29 averages, what is the PSD random error as a percentage?', NULL, '$1/\sqrt{29} = 0.186$.', NULL, NULL, 18.6, 0.03, '%');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm3-problems', 'm3-problems-5', 4, 'numeric', 1, 'A spectrogram window of 100 ms resolves what frequency spacing?', NULL, '$1/0.1 = 10$ Hz.', NULL, NULL, 10, 0.02, 'Hz');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm3-problems', 'm3-problems-6', 5, 'numeric', 3, 'With coherence γ² = 0.9 and 50 averages, what is the FRF gain''s random error as a percentage?', NULL, '$\sqrt{0.1}/(0.949\sqrt{100}) = 0.033$.', NULL, NULL, 3.3, 0.05, '%');
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('signals-dsp-estimation', 'm4-problems', 'm4', 'Noise and least-squares problems', 'Averaging, weighting and fitting.', 'problems', 3);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm4-problems', 'm4-problems-1', 0, 'numeric', 1, 'A sensor has 1.57 mg rms white noise. What does the average of 100 independent samples have?', NULL, '$1.57/\sqrt{100} = 0.157$ mg.', NULL, NULL, 0.157, 0.01, 'mg');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm4-problems', 'm4-problems-2', 1, 'numeric', 1, 'Two sensors have σ = 2 and σ = 1. What weight goes to the better one?', NULL, '$1/(1/4 + 1) = 0.8$.', NULL, NULL, 0.8, 0.01, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm4-problems', 'm4-problems-3', 2, 'numeric', 2, 'What is the combined standard deviation of those two sensors with optimal weights?', NULL, '$1/\sqrt{1/4 + 1} = 0.894$.', NULL, NULL, 0.894, 0.01, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm4-problems', 'm4-problems-4', 3, 'numeric', 2, 'Fit y = mt + c to (0, 1.1), (1, 2.9), (2, 5.2) by least squares. What is the slope m?', NULL, '$m = \sum(t-\bar t)(y-\bar y)/\sum(t-\bar t)^2 = 4.1/2 = 2.05$.', NULL, NULL, 2.05, 0.01, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm4-problems', 'm4-problems-5', 4, 'mcq', 2, 'Averaging 1 000 samples does not reduce the error of a sensor with a slow drift. Why?', NULL, 'Averaging reduces independent noise; a slowly varying drift is the same in neighbouring samples.', '["Drift is too small","Drift is correlated in time, so the samples are not independent","Averages never work","The drift is Gaussian"]', 1, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('signals-dsp-estimation', 'm5-problems', 'm5', 'Kalman problems', 'Gain, variance, delay and consistency.', 'problems', 4);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm5-problems', 'm5-problems-1', 0, 'numeric', 1, 'A scalar filter has P⁻ = 1.01 and R = 0.25. What is the Kalman gain K?', NULL, '$K = 1.01/(1.01 + 0.25) = 0.8016$.', NULL, NULL, 0.8016, 0.01, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm5-problems', 'm5-problems-2', 1, 'numeric', 2, 'After that update with K = 0.8016, what is the new variance P = (1 − K)P⁻?', NULL, '$(1 - 0.8016)\times1.01 = 0.2004$.', NULL, NULL, 0.2004, 0.02, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm5-problems', 'm5-problems-3', 2, 'numeric', 1, 'The estimate is 0, the measurement is 1.1 and K = 0.8016. What is the updated estimate?', NULL, '$0 + 0.8016\times1.1 = 0.882$.', NULL, NULL, 0.8818, 0.01, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm5-problems', 'm5-problems-4', 3, 'numeric', 1, 'A barometer reading is 50 ms old and the rocket climbs at 300 m/s. What is the error if applied as current?', NULL, '$300\times0.05 = 15$ m.', NULL, NULL, 15, 0.02, 'm');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm5-problems', 'm5-problems-5', 4, 'numeric', 2, 'What NIS value is exceeded only about 5 percent of the time for one measurement?', NULL, 'The 95th percentile of chi-squared with 1 degree of freedom is 3.84.', NULL, NULL, 3.84, 0.01, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('signals-dsp-estimation', 'm5-problems', 'm5-problems-6', 5, 'written', 3, 'The filter''s NIS is above 3.84 most of the time. Give two possible causes and what you would change.', NULL, 'The innovations are larger than the filter expects, so it is over-confident. Either the measurement noise R is set too low (use the sensor''s true noise from a stationary test and raise R), or the process noise Q is too low so the filter cannot follow real changes (raise Q or add an acceleration or bias state). A third cause is a modelling error, such as a measurement delay or an unmodelled bias; check the time alignment and add a bias state.', NULL, NULL, NULL, NULL, NULL);
